-- Review requests and restoration retain immutable snapshots and refuse stale callers.
select no_plan();
select tests.create_catalogue_fixture();
select ok(not has_function_privilege('anon','public.submit_effect_version(uuid,jsonb,text)','execute'),'public cannot submit');
select ok(not has_function_privilege('anon','private.submit_effect_version(uuid,jsonb,text)','execute'),'public cannot bypass submit wrapper');
select ok(not has_function_privilege('anon','public.restore_effect_version(uuid,uuid,uuid,jsonb,text)','execute'),'public cannot restore');
select ok(not has_function_privilege('anon','private.restore_effect_version(uuid,uuid,uuid,jsonb,text)','execute'),'public cannot bypass restore wrapper');
select tests.act_as('organisation_owner');
select throws_ok($$select public.submit_effect_version('50000000-0000-0000-0000-000000000002',tests.design_fixture(),'Please review')$$,'42501',null,'retailer cannot submit');
select throws_ok($$select public.restore_effect_version('40000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000002',tests.design_fixture(),'test')$$,'42501',null,'retailer cannot restore');
reset role;
select tests.act_as('platform_staff');
select throws_ok($$select public.submit_effect_version('50000000-0000-0000-0000-000000000002',jsonb_set(tests.design_fixture(),'{seed}','42'),'Please review')$$,'23514',null,'stale review snapshot refused');
select lives_ok($$select public.submit_effect_version('50000000-0000-0000-0000-000000000002',tests.design_fixture(),'Please review')$$,'current draft submits');
select is((select status from public.effect_versions where id='50000000-0000-0000-0000-000000000002'),'in_review','review freezes draft');
select is((select count(*)::int from public.reviews where effect_version_id='50000000-0000-0000-0000-000000000002'),1,'one review request recorded');
select is((select reviewer_id from public.reviews where effect_version_id='50000000-0000-0000-0000-000000000002'),auth.uid(),'review request attributed to caller');
select throws_ok($$select public.save_effect_draft('50000000-0000-0000-0000-000000000002',tests.design_fixture(),'test')$$,'23514',null,'submitted snapshot cannot autosave');
select throws_ok($$select public.submit_effect_version('50000000-0000-0000-0000-000000000002',tests.design_fixture(),'Again')$$,'23514',null,'repeated request refused');
reset role;
-- An active published effect gains a separate draft that restoration must retain.
select tests.act_as('platform_staff');
create temporary table saved_checkpoint as select public.create_effect_draft('40000000-0000-0000-0000-000000000001','published-effect','Published fixture','peony',tests.design_fixture(),'test','50000000-0000-0000-0000-000000000001') as id;
select throws_ok($$select public.restore_effect_version('40000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000002',(select draft_version_id from public.effects where id='40000000-0000-0000-0000-000000000001'),tests.design_fixture(),'test')$$,'P0002',null,'cross-effect target refused');
select lives_ok($$select public.restore_effect_version('40000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001',(select draft_version_id from public.effects where id='40000000-0000-0000-0000-000000000001'),tests.design_fixture(),'test')$$,'draft restores from published history');
select is((select status from public.effect_versions where id=(select id from saved_checkpoint)),'superseded','previous draft retained as immutable history');
select is((select design from public.effect_versions where id=(select id from saved_checkpoint)),tests.design_fixture(),'checkpoint payload retained');
select is((select count(*)::int from public.effect_versions where effect_id='40000000-0000-0000-0000-000000000001'),4,'restoration creates a new version');
select is((select status from public.effect_versions where id=(select draft_version_id from public.effects where id='40000000-0000-0000-0000-000000000001')),'draft','restored version is editable');
select throws_ok(format('select public.restore_effect_version(%L,%L,%L,tests.design_fixture(),%L)','40000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001',(select id from saved_checkpoint),'test'),'23514',null,'stale current pointer refused');
select ok(not has_function_privilege('anon','public.finish_effect_version(uuid,jsonb,text,text,integer,numeric)','execute'),'public cannot finish a draft');
select ok(not has_function_privilege('anon','private.finish_effect_version(uuid,jsonb,text,text,integer,numeric)','execute'),'public cannot bypass finish wrapper');
select throws_ok($$select public.finish_effect_version((select draft_version_id from public.effects where id='40000000-0000-0000-0000-000000000001'),jsonb_set(tests.design_fixture(),'{seed}','42'),'Wrong note','publish',100,1)$$,'23514',null,'finishing refuses stale snapshot atomically');
select is((select change_note from public.effect_versions where id=(select draft_version_id from public.effects where id='40000000-0000-0000-0000-000000000001')),'Restored version 1','failed finish retains the original note');
insert into public.poster_renders(product_version_id,renderer,framing,width,height,t_ms,path,status) values ('70000000-0000-0000-0000-000000000001','test','card',320,200,1000,'test/product.png','ready');
select lives_ok($$select public.finish_effect_version((select draft_version_id from public.effects where id='40000000-0000-0000-0000-000000000001'),tests.design_fixture(),'Reviewed publication','publish',100,1)$$,'exact snapshot publishes with note');
select is((select change_note from public.effect_versions where id=(select current_version_id from public.effects where id='40000000-0000-0000-0000-000000000001')),'Reviewed publication','publish note persisted');
select is((select status from public.poster_renders where product_version_id='70000000-0000-0000-0000-000000000001' and renderer='test'),'pending','dependent product posters are queued after an effect changes');
select * from finish();
